import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;
import java.nio.charset.StandardCharsets;

/**
 * Lightweight HTTP server designed to sit behind nginx/HAProxy reverse proxy.
 * Handles chunked transfer encoding for streaming API requests.
 * 
 * Proxy configuration assumes: proxy_http_version 1.1;
 */
public class ApiServer {

    private static final int PORT = 8080;
    private static final long MAX_BODY_SIZE = 10_000_000L;
    private static final ExecutorService pool = Executors.newFixedThreadPool(32);
    private static final Map<String, String> sessions = new ConcurrentHashMap<>();

    public static void main(String[] args) throws IOException {
        ServerSocket server = new ServerSocket(PORT);
        System.out.println("API Server listening on port " + PORT);
        while (true) {
            Socket client = server.accept();
            pool.submit(() -> handleConnection(client));
        }
    }

    private static void handleConnection(Socket client) {
        try {
            client.setSoTimeout(30000);
            InputStream raw = client.getInputStream();
            OutputStream out = client.getOutputStream();
            // Support HTTP/1.1 keep-alive: process multiple requests per connection
            while (!client.isClosed()) {
                HttpRequest req = parseRequest(raw);
                if (req == null) break;
                HttpResponse resp = routeRequest(req);
                out.write(resp.serialize());
                out.flush();
                if ("close".equalsIgnoreCase(req.getHeader("Connection"))) break;
            }
        } catch (Exception e) {
            // Connection closed or timeout
        } finally {
            try { client.close(); } catch (IOException ignored) {}
        }
    }

    private static HttpRequest parseRequest(InputStream in) throws IOException {
        String requestLine = readLine(in);
        if (requestLine == null || requestLine.isEmpty()) return null;

        String[] parts = requestLine.split(" ");
        if (parts.length < 3) return null;

        String method = parts[0];
        String path = parts[1];
        Map<String, String> headers = new LinkedHashMap<>();

        String headerLine;
        while ((headerLine = readLine(in)) != null && !headerLine.isEmpty()) {
            int colon = headerLine.indexOf(':');
            if (colon > 0) {
                String name = headerLine.substring(0, colon).trim();
                String value = headerLine.substring(colon + 1).trim();
                headers.put(name, value);
            }
        }

        byte[] body = readBody(in, headers);
        return new HttpRequest(method, path, headers, body);
    }

    /**
     * Reads the request body according to RFC 7230 precedence rules.
     * When both Transfer-Encoding and Content-Length are present,
     * the message is rejected as malformed per RFC 7230 Section 3.3.3.
     */
    private static byte[] readBody(InputStream in, Map<String, String> headers) throws IOException {
        String transferEncoding = getHeaderCaseInsensitive(headers, "Transfer-Encoding");
        String contentLength = getHeaderCaseInsensitive(headers, "Content-Length");

        // Reject ambiguous requests that have both headers - prevents smuggling
        if (transferEncoding != null && contentLength != null) {
            throw new IOException("Rejecting request with both Transfer-Encoding and Content-Length");
        }

        if (transferEncoding != null && transferEncoding.toLowerCase().contains("chunked")) {
            return readChunkedBody(in);
        } else if (contentLength != null) {
            int len = parseContentLength(contentLength);
            if (len > 0 && len < 10_000_000) {
                byte[] buf = new byte[len];
                int read = 0;
                while (read < len) {
                    int r = in.read(buf, read, len - read);
                    if (r == -1) break;
                    read += r;
                }
                return Arrays.copyOf(buf, read);
            }
        }
        return new byte[0];
    }

    /**
     * Parse Content-Length strictly - reject if multiple differing values present.
     */
    private static int parseContentLength(String value) {
        // RFC 7230 Section 3.3.2: reject if multiple values differ
        String[] values = value.split(",");
        int first = -1;
        for (String v : values) {
            try {
                int parsed = Integer.parseInt(v.trim());
                if (first == -1) {
                    first = parsed;
                } else if (parsed != first) {
                    return 0; // Reject ambiguous Content-Length
                }
            } catch (NumberFormatException e) {
                return 0;
            }
        }
        return first >= 0 ? first : 0;
    }

    private static byte[] readChunkedBody(InputStream in) throws IOException {
        ByteArrayOutputStream body = new ByteArrayOutputStream();
        long total = 0;
        while (true) {
            String sizeLine = readLine(in);
            if (sizeLine == null) break;
            // Strip chunk extensions per RFC 7230 Section 4.1.1
            int semi = sizeLine.indexOf(';');
            String sizeStr = (semi >= 0) ? sizeLine.substring(0, semi).trim() : sizeLine.trim();
            int chunkSize;
            try {
                chunkSize = Integer.parseInt(sizeStr, 16);
            } catch (NumberFormatException e) {
                break;
            }
            if (chunkSize < 0) {
                throw new IOException("Invalid negative chunk size");
            }
            if (chunkSize == 0) {
                readLine(in); // consume trailing CRLF
                break;
            }
            // Enforce a total body size limit to prevent memory exhaustion (CWE-770)
            total += chunkSize;
            if (total > MAX_BODY_SIZE) {
                throw new IOException("Chunked body exceeds maximum allowed size");
            }
            byte[] chunk = new byte[chunkSize];
            int read = 0;
            while (read < chunkSize) {
                int r = in.read(chunk, read, chunkSize - read);
                if (r == -1) break;
                read += r;
            }
            body.write(chunk, 0, read);
            readLine(in); // consume CRLF after chunk data
        }
        return body.toByteArray();
    }

    private static String getHeaderCaseInsensitive(Map<String, String> headers, String name) {
        for (Map.Entry<String, String> entry : headers.entrySet()) {
            if (entry.getKey().equalsIgnoreCase(name)) {
                return entry.getValue();
            }
        }
        return null;
    }

    private static HttpResponse routeRequest(HttpRequest req) {
        switch (req.path) {
            case "/api/health":
                return new HttpResponse(200, "{\"status\":\"ok\"}");
            case "/api/admin/users":
                return handleAdminUsers(req);
            case "/api/transfer":
                return handleTransfer(req);
            default:
                return new HttpResponse(404, "{\"error\":\"not found\"}");
        }
    }

    private static HttpResponse handleAdminUsers(HttpRequest req) {
        String auth = req.getHeader("X-Authenticated-User");
        if (auth == null || !auth.equals("admin")) {
            return new HttpResponse(403, "{\"error\":\"forbidden\"}");
        }
        return new HttpResponse(200, "{\"users\":[\"admin\",\"user1\",\"user2\"]}");
    }

    private static HttpResponse handleTransfer(HttpRequest req) {
        String auth = req.getHeader("X-Authenticated-User");
        if (auth == null) {
            return new HttpResponse(401, "{\"error\":\"unauthorized\"}");
        }
        String bodyStr = new String(req.body, StandardCharsets.UTF_8);
        return new HttpResponse(200, "{\"result\":\"processed\",\"by\":\"" + auth + "\"}");
    }

    private static String readLine(InputStream in) throws IOException {
        StringBuilder sb = new StringBuilder();
        int c;
        while ((c = in.read()) != -1) {
            if (c == '\r') {
                int next = in.read();
                if (next == '\n') break;
                sb.append((char) c);
                if (next != -1) sb.append((char) next);
            } else if (c == '\n') {
                break;
            } else {
                sb.append((char) c);
            }
        }
        return (c == -1 && sb.length() == 0) ? null : sb.toString();
    }

    static class HttpRequest {
        final String method, path;
        final Map<String, String> headers;
        final byte[] body;

        HttpRequest(String method, String path, Map<String, String> headers, byte[] body) {
            this.method = method;
            this.path = path;
            this.headers = headers;
            this.body = body;
        }

        String getHeader(String name) {
            return getHeaderCaseInsensitive(headers, name);
        }
    }

    static class HttpResponse {
        final int status;
        final String body;

        HttpResponse(int status, String body) {
            this.status = status;
            this.body = body;
        }

        byte[] serialize() {
            String resp = "HTTP/1.1 " + status + " OK\r\n" +
                    "Content-Type: application/json\r\n" +
                    "Content-Length: " + body.getBytes(StandardCharsets.UTF_8).length + "\r\n" +
                    "Connection: keep-alive\r\n" +
                    "\r\n" + body;
            return resp.getBytes(StandardCharsets.UTF_8);
        }
    }
}
